1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	import java.util.Objects;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	
11	/**
12	 * Flags a newly built owner as a soft duplicate of an existing owner. Unlike the hard
13	 * {@link EnsureUniqueIdentity} check (which rejects an occupied household as a 409), a
14	 * soft match still creates the owner: it fires when the new owner shares an existing
15	 * owner's last name (case-insensitive) and postcode but has a different telephone. The new
16	 * owner is stamped with {@code possibleDuplicate=true} and {@code possibleDuplicateOf} set
17	 * to the matching owner's id; when no match exists the flag is false and the id null.
18	 *
19	 * <p>An owner created as a declared household member ({@code sharesHousehold=true}, which
20	 * bypassed the duplicate block) is never flagged: a declared member is not a suspected
21	 * duplicate.
22	 *
23	 * <p>Runs after {@link BuildOwner} (so the owner's normalized fields are set) and before
24	 * {@link SaveOwner} (so the new owner is not yet persisted and cannot match itself), and
25	 * mutates the built owner in place so the flag is stored and returned with it. The first
26	 * matching existing owner encountered wins.
27	 */
28	public class AssignPossibleDuplicate {
29	
30	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
31	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
32	            owner.setPossibleDuplicate(false);
33	            owner.setPossibleDuplicateOf(null);
34	            return;
35	        }
36	        for (Owner existing : ownerRepository.findAll()) {
37	            if (Boolean.TRUE.equals(existing.getDeleted())) {
38	                continue; // a soft-deleted owner is not a duplicate to flag against
39	            }
40	            if (isPossibleDuplicate(owner, existing)) {
41	                owner.setPossibleDuplicate(true);
42	                owner.setPossibleDuplicateOf(existing.getId());
43	                return;
44	            }
45	        }
46	        owner.setPossibleDuplicate(false);
47	        owner.setPossibleDuplicateOf(null);
48	    }
49	
50	    /**
51	     * Whether {@code candidate} is a soft duplicate of {@code existing}: the same last
52	     * name (case-insensitive) and the same non-blank postcode, but a different telephone
53	     * (so it is not the same person re-registering).
54	     */
55	    private static boolean isPossibleDuplicate(Owner candidate, Owner existing) {
56	        return samePostcode(candidate.getPostcode(), existing.getPostcode())
57	            && sameLastName(candidate.getLastName(), existing.getLastName())
58	            && !Objects.equals(candidate.getTelephone(), existing.getTelephone());
59	    }
60	
61	    private static boolean samePostcode(String a, String b) {
62	        return a != null && !a.isBlank() && a.equals(b);
63	    }
64	
65	    private static boolean sameLastName(String a, String b) {
66	        return fold(a).equals(fold(b));
67	    }
68	
69	    private static String fold(String value) {
70	        return value == null ? "" : value.strip().toLowerCase(Locale.ROOT);
71	    }
72	}
